<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Client\Infrastructure\Driven;

use Override;
use Civi\Lughauth\Shared\Value\Random;
use Civi\Lughauth\Shared\Security\AesCypherService;
use Civi\Lughauth\Features\Access\Tenant\Domain\Gateway\TenantReadGateway;
use Civi\Lughauth\Features\Access\TenantConfig\Domain\Gateway\TenantConfigReadGateway;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClient;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClientAttributes;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClientRef;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\Gateway\TrustedClientReadGateway;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\Gateway\TrustedClientWriteGateway;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientAllowedRedirectsItem;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientAllowedRedirectsListRef;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientAllowedRedirectsUidVO;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientAllowedRedirectsUrlVO;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientSecretOauthVO;
use Civi\Lughauth\Features\OAuth\Client\Domain\DynamicClientData;
use Civi\Lughauth\Features\OAuth\Client\Domain\DynamicClientRequest;
use Civi\Lughauth\Features\OAuth\Client\Domain\Gateway\DynamicClientGateway;

/**
 * Infrastructure adapter that implements DynamicClientGateway by persisting dynamically
 * registered clients as TrustedClient entities in the Access bounded context.
 *
 * This adapter maps between the DynamicClient* domain value objects and the TrustedClient
 * aggregate, acting as the primary anti-corruption layer for RFC 7591/7592 operations. The
 * registration access token is stored as a SHA-256 hash so that a plain-text token is never
 * kept at rest. The client secret is encrypted at rest using AesCypherService.
 *
 * The registration policy is resolved by reading the tenant's TenantConfig record; when
 * neither the tenant nor the config is found, "disabled" is returned as a safe default.
 * All redirect URIs are stored as individual TrustedClientAllowedRedirects value objects,
 * each assigned a fresh COMB UUID, so the Access layer can manage them independently.
 */
final class DynamicClientAdapter implements DynamicClientGateway
{
    public function __construct(
        private readonly TrustedClientWriteGateway $writer,
        private readonly TrustedClientReadGateway $reader,
        private readonly TenantReadGateway $tenants,
        private readonly TenantConfigReadGateway $tenantConfigs,
        private readonly AesCypherService $cypher,
    ) {
    }

    /**
     * Creates a new TrustedClient entity with the dynamically_registered flag set, storing the
     * hashed registration access token and the encrypted client secret, then returns the assigned
     * client ID and issuance timestamp.
     */
    #[Override]
    public function create(
        string $clientId,
        string $clientSecret,
        string $registrationAccessToken,
        DynamicClientRequest $request,
    ): array {
        $now = new \DateTimeImmutable();

        $attrs = (new TrustedClientAttributes())
            ->withDefaults()
            ->uid($clientId)
            ->code($clientId)
            ->secretOauth(TrustedClientSecretOauthVO::fromPlainText($this->cypher, $clientSecret))
            ->publicAllow(true)
            ->enabled(true)
            ->allowAllScopes(false)
            ->allowedRedirects($this->buildRedirectsListRef($request->redirectUris))
            ->registrationAccess(hash('sha256', $registrationAccessToken))
            ->clientName($request->clientName)
            ->logoUri($request->logoUri)
            ->clientUri($request->clientUri)
            ->policyUri($request->policyUri)
            ->tosUri($request->tosUri)
            ->tokenEndpointAuthMethod($request->tokenEndpointAuthMethod)
            ->grantTypesJson(json_encode($request->grantTypes))
            ->responseTypesJson(json_encode($request->responseTypes))
            ->dynamicallyRegistered(true)
            ->registeredAt($now)
            ->backChannelLogoutUri($request->backchannelLogoutUri)
            ->frontChannelLogoutUri($request->frontchannelLogoutUri);

        $entity = TrustedClient::create($attrs);
        $this->writer->create($entity);

        return [
            'clientId' => $clientId,
            'issuedAt' => $now->getTimestamp(),
        ];
    }

    /**
     * Looks up a dynamically registered client by UID and verifies the SHA-256 hash of the
     * provided token matches the stored value. Returns null on any mismatch or if the client
     * is not flagged as dynamically registered.
     */
    #[Override]
    public function findByClientIdAndToken(string $clientId, string $registrationAccessToken): ?DynamicClientData
    {
        $client = $this->reader->findOneByUid($clientId);

        if ($client === null) {
            return null;
        }
        if (!$client->isDynamicallyRegistered()) {
            return null;
        }
        if ($client->getRegistrationAccess() !== hash('sha256', $registrationAccessToken)) {
            return null;
        }

        return $this->mapToDynamicClientData($client);
    }

    /**
     * Acquires a pessimistic write lock on the client, validates the token hash, applies the
     * updated metadata attributes, persists the change, and returns the refreshed snapshot.
     */
    #[Override]
    public function update(string $clientId, string $registrationAccessToken, DynamicClientRequest $request): ?DynamicClientData
    {
        $client = $this->writer->findOneForUpdateByUid($clientId);

        if ($client === null) {
            return null;
        }
        if (!$client->isDynamicallyRegistered()) {
            return null;
        }
        if ($client->getRegistrationAccess() !== hash('sha256', $registrationAccessToken)) {
            return null;
        }

        $attrs = (new TrustedClientAttributes())
            ->clientName($request->clientName)
            ->logoUri($request->logoUri)
            ->clientUri($request->clientUri)
            ->policyUri($request->policyUri)
            ->tosUri($request->tosUri)
            ->tokenEndpointAuthMethod($request->tokenEndpointAuthMethod)
            ->grantTypesJson(json_encode($request->grantTypes))
            ->responseTypesJson(json_encode($request->responseTypes))
            ->allowedRedirects($this->buildRedirectsListRef($request->redirectUris))
            ->backChannelLogoutUri($request->backchannelLogoutUri)
            ->frontChannelLogoutUri($request->frontchannelLogoutUri);

        $updated = $client->update($attrs);
        $this->writer->update(new TrustedClientRef($clientId), $updated);

        return $this->mapToDynamicClientData($updated);
    }

    /**
     * Acquires a pessimistic write lock on the client, validates the token hash, and delegates
     * the physical deletion to the write gateway. Returns false on any validation failure.
     */
    #[Override]
    public function delete(string $clientId, string $registrationAccessToken): bool
    {
        $client = $this->writer->findOneForUpdateByUid($clientId);

        if ($client === null) {
            return false;
        }
        if (!$client->isDynamicallyRegistered()) {
            return false;
        }
        if ($client->getRegistrationAccess() !== hash('sha256', $registrationAccessToken)) {
            return false;
        }

        return $this->writer->delete($client->delete());
    }

    /**
     * Reads the dynamic registration policy from the tenant's configuration record.
     * Returns "disabled" when the tenant or its configuration cannot be found.
     */
    #[Override]
    public function readRegistrationPolicy(string $tenant): string
    {
        $tenantObj = $this->tenants->findOneByName($tenant);
        if ($tenantObj === null) {
            return 'disabled';
        }

        $config = $this->tenantConfigs->findOneByTenant($tenantObj);
        if ($config === null) {
            return 'disabled';
        }

        return $config->getDynamicRegistrationPolicy()?->value ?? 'disabled';
    }

    private function buildRedirectsListRef(array $uris): TrustedClientAllowedRedirectsListRef
    {
        $items = array_map(
            fn (string $uri) => new TrustedClientAllowedRedirectsItem(
                TrustedClientAllowedRedirectsUidVO::from(Random::uuid()),
                TrustedClientAllowedRedirectsUrlVO::from($uri),
                null,
            ),
            $uris
        );

        return TrustedClientAllowedRedirectsListRef::fromArray($items);
    }

    private function mapToDynamicClientData(TrustedClient $client): DynamicClientData
    {
        $redirectUris = [];
        $redirects = $client->getAllowedRedirects();
        if ($redirects !== null) {
            foreach ($redirects as $item) {
                if ($item !== null && $item->getUrl() !== null) {
                    $redirectUris[] = $item->getUrl();
                }
            }
        }

        $grantTypes = ['authorization_code'];
        if ($client->getGrantTypesJson() !== null) {
            $decoded = json_decode($client->getGrantTypesJson(), true);
            if (is_array($decoded)) {
                $grantTypes = $decoded;
            }
        }

        $responseTypes = ['code'];
        if ($client->getResponseTypesJson() !== null) {
            $decoded = json_decode($client->getResponseTypesJson(), true);
            if (is_array($decoded)) {
                $responseTypes = $decoded;
            }
        }

        $issuedAt = $client->getRegisteredAt()?->getTimestamp() ?? 0;

        return new DynamicClientData(
            clientId: (string) $client->uid(),
            redirectUris: $redirectUris,
            grantTypes: $grantTypes,
            responseTypes: $responseTypes,
            scope: null,
            tokenEndpointAuthMethod: $client->getTokenEndpointAuthMethod() ?? 'client_secret_basic',
            clientName: $client->getClientName(),
            logoUri: $client->getLogoUri(),
            clientUri: $client->getClientUri(),
            policyUri: $client->getPolicyUri(),
            tosUri: $client->getTosUri(),
            backchannelLogoutUri: $client->getBackChannelLogoutUri(),
            frontchannelLogoutUri: $client->getFrontChannelLogoutUri(),
            clientIdIssuedAt: $issuedAt,
            registrationClientUri: '',
        );
    }
}
